import java.util.*;

class Solution {
    public int countElementsWithKGreater(int[] nums, int k) {
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int n = nums.length;
        int count = 0;
        for (int x : nums) {
            // Find upper bound of x
            int l = 0, r = n;
            while (l < r) {
                int mid = (l + r) / 2;
                if (sorted[mid] <= x) l = mid + 1;
                else r = mid;
            }
            int strictlyGreater = n - l;
            if (strictlyGreater >= k) count++;
        }
        return count;
    }
}

var countElementsWithKGreater = function(nums, k) {
    const sorted = [...nums].sort((a, b) => a - b);
    const n = nums.length;
    let count = 0;
    for (const x of nums) {
        let l = 0, r = n;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (sorted[mid] <= x) l = mid + 1;
            else r = mid;
        }
        const strictlyGreater = n - l;
        if (strictlyGreater >= k) count++;
    }
    return count;
};
